@OptIn(ExperimentalMaterial3AdaptiveApi::class)
Box(
    modifier = Modifier
        .height(440.dp)
        .clip(MonarchTheme.shapes.lg)
        .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg),
) {
NavigableListDetailPaneScaffold(
    navigator = navigator,
    listPane = {
        AnimatedPane {
            LazyColumn {
                itemsIndexed(items = conversations, key = { _, item -> item.subject }) { index, conversation ->
                    MonarchListRow(
                        headlineContent = { Text(conversation.subject) },
                        supportingContent = { Text(conversation.from + " · " + conversation.preview) },
                        selected = navigator.currentDestination?.contentKey == index,
                        divider = true,
                        onClick = {
                            scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, index) }
                        },
                    )
                }
            }
        }
    },
    detailPane = {
        AnimatedPane {
            val index = navigator.currentDestination?.contentKey
            if (index == null) {
                MonarchEmptyState(title = "Pick a conversation", message = "Choose one from the list.")
            } else {
                val conversation = conversations[index]
                Column(
                    modifier = Modifier.padding(MonarchTheme.spacing.space4),
                    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                ) {
                    Row(verticalAlignment = Alignment.Top) {
                        MonarchText(text = conversation.subject, modifier = Modifier.weight(1f), style = MonarchTextStyle.Title)
                        MonarchIconButton(
                            label = "Ticket details",
                            onClick = {
                                scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Extra, index) }
                            },
                        ) {
                            MonarchIcon(SampleIcons.Columns, contentDescription = null)
                        }
                    }
                    MonarchBadge(text = {{status.label}}, tone = {{status.tone|tone}})
                    MonarchText(text = "From " + conversation.from, color = MonarchTheme.colors.textMuted)
                    MonarchText(text = conversation.preview)
                }
            }
        }
    },
    extraPane = {
        AnimatedPane {
            val index = navigator.currentDestination?.contentKey
            if (index != null) {
                MonarchSectionCard(title = "Ticket details") {
                    MonarchDescriptionList(
                        items = listOf(
                            MonarchDescriptionItem("Requester", conversations[index].from),
                            MonarchDescriptionItem("Priority", {{priority}}),
                            MonarchDescriptionItem("Assignee", null),
                        ),
                        emptyLabel = "—",
                    )
                }
            }
        }
    },
)
}

