class Conversation(val subject: String, val from: String, val preview: String)
val conversations = remember {
    listOf(
        Conversation({{conversations.0.subject}}, {{conversations.0.from}}, {{conversations.0.preview}}),
        Conversation({{conversations.1.subject}}, {{conversations.1.from}}, {{conversations.1.preview}}),
        Conversation({{conversations.2.subject}}, {{conversations.2.from}}, {{conversations.2.preview}}),
    )
}
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
LaunchedEffect(Unit) { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, {{selected}}) }

